import pathlib, subprocess, tempfile
root = pathlib.Path(__file__).resolve().parent
source = (root / "main.swift").read_text()
helpers = source.split("final class Workspace")[0] + source[source.index("func pdfURLs"):source.index("final class ActionDropView")]
fixture = 'let source = PDFDocument()\nfor label in ["First", "Second", "Third"] {\n let image = NSImage(size: NSSize(width: 300, height: 400))\n image.lockFocus()\n NSColor.white.setFill(); NSRect(x: 0,y: 0,width: 300,height: 400).fill()\n (label as NSString).draw(at: NSPoint(x: 20,y: 200), withAttributes: [.font: NSFont.systemFont(ofSize: 24), .foregroundColor: NSColor.black])\n image.unlockFocus()\n source.insert(PDFPage(image: image)!, at: source.pageCount)\n}\nlet sourceURL = URL(fileURLWithPath: "/tmp/workbench-source.pdf")\nassert(source.write(to: sourceURL))\nlet before = try Data(contentsOf: sourceURL)\nlet indexes = [2,0,1]\nlet output = reorderedDocument(indexes.map { PageItem(page: source.page(at: $0)!, original: $0+1) })!\nlet result = URL(fileURLWithPath: "/tmp/workbench-reordered.pdf")\nassert(output.write(to: result))\nlet reopened = PDFDocument(url: result)!\nassert(reopened.pageCount == 3)\nfor i in 0..<3 {\n let a = reopened.page(at: i)!.thumbnail(of: NSSize(width: 100,height: 140), for: .mediaBox).tiffRepresentation!\n let b = source.page(at: indexes[i])!.thumbnail(of: NSSize(width: 100,height: 140), for: .mediaBox).tiffRepresentation!\n assert(a == b, "Page order mismatch")\n}\nlet after = try Data(contentsOf: sourceURL)\nassert(after == before)\nlet merged = reorderedDocument([PageItem(page: source.page(at: 0)!, original: 1), PageItem(page: reopened.page(at: 0)!, original: 1)])!\nassert(merged.pageCount == 2)\nlet board = NSPasteboard.withUniqueName()\nboard.writeObjects([sourceURL as NSURL, result as NSURL])\nassert(pdfURLs(board).count == 2)\nboard.clearContents(); board.writeObjects([sourceURL as NSURL, URL(fileURLWithPath: "/tmp/test.txt") as NSURL])\nassert(pdfURLs(board).isEmpty)\nboard.clearContents(); board.writeObjects(["not a file" as NSString])\nassert(pdfURLs(board).isEmpty)\nboard.releaseGlobally()\nprint("PASS: reorder round-trip, original bytes unchanged, merge, multi-PDF drops, mixed/non-file rejection")\n'
with tempfile.TemporaryDirectory(prefix="pdf-workbench-tests-") as folder:
    path = pathlib.Path(folder) / "test.swift"
    path.write_text(helpers + fixture)
    subprocess.run(["xcrun", "swift", str(path)], check=True)
